parameters.jsCode:
const dataset = {
  "interacciones": [
    {
      "id": "msg_001",
      "autor": "Carlos Mendoza",
      "canal": "#logros-y-empleos",
      "tipo": "testimonio",
      "texto": "Quiero compartirles que hoy firmé mi contrato formal como Desarrollador Junior Cloud en una consultora internacional. Todo lo aprendido en la formación de Oracle ONE y los laboratorios prácticos marcaron la diferencia absoluta en mi prueba técnica. Infinitas gracias a la comunidad por el apoyo constante!"
    },
    {
      "id": "msg_002",
      "autor": "Lucía Fernández",
      "canal": "#dudas-programacion",
      "tipo": "pregunta_tecnica",
      "texto": "Hola comunidad, estoy teniendo un problema con una llamada a la API de Gemini en Python. Me sale un error de ResourceExhausted cuando envío más de 10 peticiones seguidas. ¿Alguien ha implementado exponential backoff o manejo de rate limits con la librería oficial de Google GenAI?"
    },
    {
      "id": "msg_003",
      "autor": "Mateo Rivas",
      "canal": "#logros-y-empleos",
      "tipo": "testimonio",
      "texto": "Ayer me confirmaron mi primer contrato como Data Analyst para una startup de Chile gracias a los proyectos que desarrollamos en las formaciones de Alura y Oracle ONE. No se rindan, el esfuerzo constante rinde frutos!"
    },
    {
      "id": "msg_004",
      "autor": "Andrea Gómez",
      "canal": "#dudas-cloud-oci",
      "tipo": "pregunta_tecnica",
      "texto": "Hola a todos, estoy intentando subir archivos a OCI Object Storage usando el SDK de Python pero me arroja un error 401 NotAuthenticated. ¿Cómo debo configurar las claves API en el archivo ~/.oci/config para la instancia VM?"
    },
    {
      "id": "msg_005",
      "autor": "Sebastián Ramos",
      "canal": "#proyectos-showcase",
      "tipo": "showcase",
      "texto": "Acabo de desplegar mi bot de Telegram con IA usando Gemini Flash y OCI Compute Always Free. Pueden probarlo y darme feedback: https://t.me/sebas_oracle_bot. Todo el backend corre en un contenedor Docker con menos de 500MB de RAM!"
    },
    {
      "id": "msg_006",
      "autor": "Valeria Silva",
      "canal": "#feedback-cursos",
      "tipo": "feedback",
      "texto": "El módulo de Prompt Engineering y Few-Shot Learning estuvo genial. Me gustaría que agregaran una clase extra sobre cómo prevenir prompt injection en sistemas que leen entradas de usuarios en foros públicos."
    },
    {
      "id": "msg_007",
      "autor": "Martín Peña",
      "canal": "#dudas-gemini-api",
      "tipo": "pregunta_tecnica",
      "texto": "Alguien sabe cuál es el límite de tokens por minuto (TPM) en la capa gratuita de Google Gemini 1.5 Flash cuando enviamos peticiones por streaming?"
    },
    {
      "id": "msg_008",
      "autor": "Daniela Paredes",
      "canal": "#logros-y-empleos",
      "tipo": "testimonio",
      "texto": "Presenté la demo de mi proyecto de Hackathon a mi jefe actual en el área de soporte y me ascendieron a Líder Técnico de Automatización de Procesos. ¡Este programa ONE realmente transforma vidas profesionales!"
    },
    {
      "id": "msg_009",
      "autor": "Esteban Morales",
      "canal": "#dudas-docker",
      "tipo": "pregunta_tecnica",
      "texto": "Cuando despliego Streamlit dentro de un contenedor Docker en Ubuntu Server de OCI, no puedo acceder desde el navegador en el puerto 8501. ¿Qué reglas de seguridad debo abrir en la VCN de Oracle Cloud?"
    },
    {
      "id": "msg_010",
      "autor": "Camila Torres",
      "canal": "#feedback-cursos",
      "tipo": "feedback",
      "texto": "Me encantaría que el equipo organizador de Oracle ONE hiciera un workshop en vivo sobre cómo preparar el perfil de LinkedIn y el portafolio en GitHub para reclutadores de tecnología. La formación técnica es excelente, pero potenciar la marca personal nos daría un impulso tremendo."
    },
    {
      "id": "msg_011",
      "autor": "Javier Rojas",
      "canal": "#logros-y-empleos",
      "tipo": "testimonio",
      "texto": "Después de 6 meses de reconversión laboral desde contabilidad hacia backend con Java y Spring Boot en Oracle ONE, acabo de recibir mi oferta laboral como Desarrollador Trainee. Gracias a mis tutores y compañeros por resolver cada duda!"
    },
    {
      "id": "msg_012",
      "autor": "Paula Benítez",
      "canal": "#dudas-cloud-oci",
      "tipo": "pregunta_tecnica",
      "texto": "Una pregunta rápida: ¿cuál es la mejor práctica para automatizar el respaldo diario de una base de datos Oracle Autonomous Database (Always Free) hacia OCI Object Storage usando OCI CLI o cron jobs?"
    },
    {
      "id": "msg_013",
      "autor": "Tomás Herrera",
      "canal": "#proyectos-showcase",
      "tipo": "showcase",
      "texto": "Diseñé un clasificador de sentimientos de tickets de soporte técnico con Gemini 1.5 Pro y FastAPI. Logramos un 92% de precisión comparado con la categorización manual humana. Les comparto el repositorio con la documentación completa."
    },
    {
      "id": "msg_014",
      "autor": "Gabriel Medina",
      "canal": "#dudas-programacion",
      "tipo": "pregunta_tecnica",
      "texto": "¿Cómo puedo forzar a que Google Gemini siempre responda con un esquema JSON estricto en Python sin que a veces incluya bloques markdown como ```json? Me está rompiendo el json.loads() en backend."
    },
    {
      "id": "msg_015",
      "autor": "Sofía Castro",
      "canal": "#logros-y-empleos",
      "tipo": "testimonio",
      "texto": "Oficialmente soy graduada de la promoción G10 de Oracle Next Education y fui seleccionada para una pasantía remunerada en ingeniería de datos en una multinacional de telecomunicaciones. ¡Los sueños se cumplen estudiando con disciplina!"
    }
  ]
};

// Devuelve los 15 registros como items independientes listos para Gemini
return dataset.interacciones.map(item => ({ json: item }));

